import{_ as e,o as a,c as o,ao as l}from"./chunks/framework.D5i_F4hf.js";const i="/AdriaArrayGeometryPicker.jl/previews/PR21/assets/window_horizontal.27nle-XR.png",n="/AdriaArrayGeometryPicker.jl/previews/PR21/assets/panel_topography_horizontal.7Sy0Gwt6.png",y=JSON.parse('{"title":"Horizontal slices","description":"","frontmatter":{},"headers":[],"relativePath":"manual/horizontal.md","filePath":"manual/horizontal.md","lastUpdated":null}'),d={name:"manual/horizontal.md"};function r(s,t,h,c,p,g){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="Horizontal-slices" tabindex="-1">Horizontal slices <a class="header-anchor" href="#Horizontal-slices" aria-label="Permalink to &quot;Horizontal slices {#Horizontal-slices}&quot;">​</a></h1><p>A profile file can also hold a horizontal slice: a map of the data at a fixed depth. The picker recognises the type of profile when it loads the file and adapts the window.</p><p><img src="'+i+'" alt=""></p><h2 id="What-changes" tabindex="-1">What changes <a class="header-anchor" href="#What-changes" aria-label="Permalink to &quot;What changes {#What-changes}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">Vertical profile</th><th style="text-align:left;">Horizontal slice</th></tr></thead><tbody><tr><td style="text-align:left;">profile axis</td><td style="text-align:left;">distance along the profile (km) × depth (km)</td><td style="text-align:left;">longitude × latitude, with the depth of the slice as title</td></tr><tr><td style="text-align:left;">aspect ratio</td><td style="text-align:left;">free</td><td style="text-align:left;">a degree of longitude is drawn <code>cos(latitude)</code> times as long as a degree of latitude, so the map is not distorted</td></tr><tr><td style="text-align:left;">topography axis</td><td style="text-align:left;">above the profile</td><td style="text-align:left;">hidden</td></tr><tr><td style="text-align:left;">topography</td><td style="text-align:left;">line in the topography axis</td><td style="text-align:left;">heatmap or contour lines on top of the volume data</td></tr><tr><td style="text-align:left;">volume data fields</td><td style="text-align:left;">fields of the volume data</td><td style="text-align:left;">in addition, the depth of each surface data set (<code>&lt;name&gt;: depth</code>)</td></tr><tr><td style="text-align:left;">surface data</td><td style="text-align:left;">lines along the profile</td><td style="text-align:left;">contour line where the surface crosses the depth of the slice</td></tr><tr><td style="text-align:left;">point data</td><td style="text-align:left;">projected onto the profile</td><td style="text-align:left;">at their longitude and latitude</td></tr><tr><td style="text-align:left;">map overview</td><td style="text-align:left;">line from <strong>A</strong> to <strong>B</strong></td><td style="text-align:left;">box around the slice, labelled with its depth</td></tr><tr><td style="text-align:left;">picks</td><td style="text-align:left;"><code>x</code> and <code>depth</code></td><td style="text-align:left;">longitude and latitude</td></tr></tbody></table><h2 id="Topography-on-a-horizontal-slice" tabindex="-1">Topography on a horizontal slice <a class="header-anchor" href="#Topography-on-a-horizontal-slice" aria-label="Permalink to &quot;Topography on a horizontal slice {#Topography-on-a-horizontal-slice}&quot;">​</a></h2><p><img src="'+n+'" alt=""></p><p>The topography panel of a horizontal slice has:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Control</th><th style="text-align:left;">What it does</th></tr></thead><tbody><tr><td style="text-align:left;">data set dropdown</td><td style="text-align:left;">Only if the profile has several topography data sets: which one to show.</td></tr><tr><td style="text-align:left;">mode dropdown</td><td style="text-align:left;"><strong>Heatmap</strong>: the topography as a semi-transparent heatmap (colormap <code>oleron</code>, centred on sea level). <strong>Contours</strong>: contour lines of the topography. <strong>Off</strong>: no topography.</td></tr><tr><td style="text-align:left;"><strong>opacity</strong> slider</td><td style="text-align:left;">The opacity of the topography heatmap. Lower it to see more of the volume data below.</td></tr><tr><td style="text-align:left;"><strong>Contour levels</strong></td><td style="text-align:left;">The elevations of the contour lines, for example <code>0</code> for the coastline (the default) or <code>-2, 0, 2</code>. Press Enter.</td></tr></tbody></table><h2 id="Picking-on-a-horizontal-slice" tabindex="-1">Picking on a horizontal slice <a class="header-anchor" href="#Picking-on-a-horizontal-slice" aria-label="Permalink to &quot;Picking on a horizontal slice {#Picking-on-a-horizontal-slice}&quot;">​</a></h2><p>Picking works as on a vertical profile (see <a href="/AdriaArrayGeometryPicker.jl/previews/PR21/manual/picking#Picking">Picking</a>), but the picks are positions on the map. In a saved pick file:</p><ul><li><p><code>lon</code> and <code>lat</code> hold the picked position,</p></li><li><p><code>depth</code> holds the depth of the slice for every pick,</p></li><li><p><code>x</code> is <code>NaN</code> (there is no distance along a profile),</p></li><li><p>the metadata hold the <code>depth</code> of the slice instead of start and end coordinates.</p></li></ul><p><strong>Load Picks</strong> only accepts picks that were made on a horizontal slice at the same depth.</p>',13)])])}const x=e(d,[["render",r]]);export{y as __pageData,x as default};
